import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Button,
} from "@mui/material";

import { useEffect, useState } from "react";

import { Link } from "react-router-dom";

import API from "../services/api";

export default function MyBlogs() {

  const [blogs, setBlogs] = useState([]);

  const user = JSON.parse(
    localStorage.getItem("user")
  );

  useEffect(() => {

    const fetchBlogs = async () => {

      try {

        const response = await API.get(
          `/blogs?author=${user._id}`
        );

        setBlogs(response.data);

      } catch (error) {

        console.log(error);
      }
    };

    fetchBlogs();

  }, [user._id]);

  return (
    <Container sx={{ py: 5 }}>

      <Typography
        variant="h4"
        fontWeight={700}
        gutterBottom
      >
        My Blogs
      </Typography>

      <Grid container spacing={4}>

        {blogs.map((blog) => (

          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog._id}
          >

            <Card>

              <CardMedia
                component="img"
                height="200"
                image={blog.image}
              />

              <CardContent>

                <Typography variant="h6">
                  {blog.title}
                </Typography>

                <Button
                  component={Link}
                  to={`/blog/${blog._id}`}
                  sx={{ mt: 2 }}
                  variant="contained"
                >
                  Read More
                </Button>

              </CardContent>

            </Card>

          </Grid>
        ))}
      </Grid>
    </Container>
  );
}
